-- Historical Preview SQL, read from migration record. Offline reconstruction only.
-- Must be followed by later audit and least-privilege hardening; never deploy independently.
create table admin.admin_mfa_status (auth_user_id uuid primary key references admin.admin_profiles(auth_user_id) on delete restrict, totp_verified_factor_count int not null default 0, has_verified_totp boolean not null default false, last_factor_verified_at timestamptz, last_synced_at timestamptz not null default now(), enrollment_required boolean not null default true);
create table admin.admin_recovery_codes (id uuid primary key default gen_random_uuid(), auth_user_id uuid not null references admin.admin_profiles(auth_user_id) on delete restrict, code_hash text not null, code_index smallint not null, used_at timestamptz, created_at timestamptz not null default now(), invalidated_at timestamptz);
create index recovery_codes_user on admin.admin_recovery_codes (auth_user_id, used_at);
create table admin.admin_session_registry (session_id uuid primary key, auth_user_id uuid not null references admin.admin_profiles(auth_user_id) on delete restrict, aal_at_issue text, ip inet, user_agent text, created_at timestamptz not null default now(), last_seen_at timestamptz, revoked_at timestamptz, revoked_by uuid references admin.admin_profiles(auth_user_id) on delete restrict, revoke_reason text);
create index session_registry_user on admin.admin_session_registry (auth_user_id, revoked_at);
create table admin.admin_step_up_events (id uuid primary key default gen_random_uuid(), auth_user_id uuid not null references admin.admin_profiles(auth_user_id) on delete restrict, session_id uuid not null, action_key text not null, resource_key text, method text not null check (method='totp'), amr_totp_timestamp timestamptz, verified_at timestamptz not null default now(), expires_at timestamptz not null, consumed_at timestamptz, ip inet, check (expires_at <= verified_at + interval '10 minutes'));
create table security.login_attempts (id bigint generated always as identity primary key, attempted_at timestamptz not null default now(), email_attempted citext, auth_user_id uuid references auth.users(id) on delete set null, outcome text not null check (outcome in ('success','bad_password','mfa_failed','totp_failed','recovery_code_failed','blocked_signup','rate_limited','unknown_user')), ip inet, user_agent text, aal_reached text);
create index login_attempts_email on security.login_attempts (email_attempted, attempted_at);
create table admin.account_recovery_events (id uuid primary key default gen_random_uuid(), auth_user_id uuid not null references admin.admin_profiles(auth_user_id) on delete restrict, event_type text not null check (event_type in ('recovery_code_used','recovery_codes_regenerated','factor_reset_requested','factor_reset_completed','password_reset_requested','password_reset_completed','owner_recovery')), requested_by uuid references admin.admin_profiles(auth_user_id) on delete restrict, ip inet, created_at timestamptz not null default now(), completed_at timestamptz, metadata jsonb not null default '{}'::jsonb);
create table audit.audit_log (id bigint generated always as identity primary key, prev_hash bytea not null, row_hash bytea not null unique, occurred_at timestamptz not null default now(), actor_auth_user_id uuid, actor_profile_id uuid references admin.admin_profiles(auth_user_id) on delete set null, actor_role_snapshot text[], action text not null, resource_type text not null, resource_id text, outcome text not null check (outcome in ('success','denied','failed')), aal_at_action text, ip inet, user_agent text, request_id uuid, before_state jsonb, after_state jsonb, reason text, metadata jsonb not null default '{}'::jsonb);
create index audit_log_time on audit.audit_log (occurred_at desc);
create index audit_log_actor on audit.audit_log (actor_auth_user_id, occurred_at desc);
create index audit_log_resource on audit.audit_log (resource_type, resource_id);
create index audit_log_request on audit.audit_log (request_id);
create table audit.audit_chain_head (id boolean primary key check (id=true), last_id bigint not null default 0, last_row_hash bytea not null default decode(repeat('00',32),'hex'), updated_at timestamptz not null default now());
insert into audit.audit_chain_head (id) values (true);
create table security.security_events (id uuid primary key default gen_random_uuid(), occurred_at timestamptz not null default now(), event_type text not null check (event_type in ('suspicious_login','repeated_failures','mfa_failure','factor_removed','session_revoked','unauthorized_access_attempt','aal_violation','recovery_code_misuse','invite_abuse','other')), severity text not null check (severity in ('info','low','medium','high','critical')), auth_user_id uuid, actor_auth_user_id uuid, ip inet, user_agent text, detail jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index security_events_type on security.security_events (event_type, occurred_at);
create table security.security_alerts (id uuid primary key default gen_random_uuid(), event_id uuid references security.security_events(id) on delete restrict, title text not null, severity text not null check (severity in ('info','low','medium','high','critical')), status text not null default 'open' check (status in ('open','acknowledged','investigating','resolved','dismissed')), assigned_to uuid references admin.admin_profiles(auth_user_id) on delete restrict, resolution_note text, resolved_by uuid references admin.admin_profiles(auth_user_id) on delete restrict, resolved_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index security_alerts_event on security.security_alerts (event_id);
alter table admin.admin_mfa_status enable row level security; alter table admin.admin_recovery_codes enable row level security; alter table admin.admin_session_registry enable row level security; alter table admin.admin_step_up_events enable row level security; alter table security.login_attempts enable row level security; alter table admin.account_recovery_events enable row level security; alter table audit.audit_log enable row level security; alter table audit.audit_chain_head enable row level security; alter table security.security_events enable row level security; alter table security.security_alerts enable row level security;
revoke all on admin.admin_mfa_status, admin.admin_recovery_codes, admin.admin_session_registry, admin.admin_step_up_events, security.login_attempts, admin.account_recovery_events, audit.audit_log, audit.audit_chain_head, security.security_events, security.security_alerts from anon, authenticated;
grant select (session_id, created_at, last_seen_at, user_agent, revoked_at) on admin.admin_session_registry to authenticated;
create policy mfa_status_own on admin.admin_mfa_status for select to authenticated using (auth.uid()=auth_user_id);
create policy mfa_status_security on admin.admin_mfa_status for select to authenticated using (admin.has_permission('security.read'));
create policy sessions_own on admin.admin_session_registry for select to authenticated using (auth.uid()=auth_user_id);
create policy sessions_security on admin.admin_session_registry for select to authenticated using (admin.has_permission('security.read'));
create policy audit_read on audit.audit_log for select to authenticated using (admin.has_permission('audit.read'));
create policy login_attempts_read on security.login_attempts for select to authenticated using (admin.has_permission('security.read'));
create policy recovery_events_read on admin.account_recovery_events for select to authenticated using (admin.has_permission('security.read'));
create policy security_events_read on security.security_events for select to authenticated using (admin.has_permission('security.read'));
create policy security_alerts_read on security.security_alerts for select to authenticated using (admin.has_permission('security.read'));
create policy security_alerts_manage on security.security_alerts for update to authenticated using (admin.has_permission('security.manage')) with check (admin.has_permission('security.manage'));
create or replace function audit._enc(p_value bytea) returns bytea language sql immutable as $$ select case when p_value is null then decode('ffffffffffffffff','hex') else int8send(coalesce(octet_length(p_value),0)::bigint) || coalesce(p_value,''::bytea) end $$;
create or replace function audit.append_audit(p_actor uuid, p_action text, p_resource_type text, p_resource_id text, p_outcome text, p_after jsonb default null, p_before jsonb default null, p_reason text default null, p_metadata jsonb default '{}'::jsonb) returns bigint language plpgsql security definer set search_path='' as $$
declare v_prev bytea; v_id bigint; v_hash bytea; v_roles text[]; v_now timestamptz := clock_timestamp();
begin
 perform pg_advisory_xact_lock(727001);
 select last_row_hash into v_prev from audit.audit_chain_head where id=true for update;
 select array_agg(role_key order by role_key) into v_roles from admin.admin_role_assignments where auth_user_id=p_actor and is_current and (expires_at is null or expires_at>now());
 insert into audit.audit_log(prev_hash,row_hash,occurred_at,actor_auth_user_id,actor_profile_id,actor_role_snapshot,action,resource_type,resource_id,outcome,aal_at_action,after_state,before_state,reason,metadata) values (v_prev, decode(repeat('00',32),'hex'), v_now, p_actor, p_actor, coalesce(v_roles,array[]::text[]), p_action, p_resource_type, p_resource_id, p_outcome, 'service', p_after, p_before, p_reason, coalesce(p_metadata,'{}'::jsonb)) returning id into v_id;
 v_hash := digest(decode('796161726c696e6b2d61756469742d763100','hex') || v_prev || audit._enc(v_id::text::bytea) || audit._enc(to_char(v_now at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')::bytea) || audit._enc(coalesce(p_actor::text,'')::bytea) || audit._enc(coalesce(p_actor::text,'')::bytea) || audit._enc(coalesce(array_to_string(v_roles,',') ,'')::bytea) || audit._enc(p_action::bytea) || audit._enc(p_resource_type::bytea) || audit._enc(coalesce(p_resource_id,'')::bytea) || audit._enc(p_outcome::bytea) || audit._enc('service'::bytea) || audit._enc(null::bytea) || audit._enc(null::bytea) || audit._enc(null::bytea) || audit._enc(coalesce(p_before::text,'{}')::bytea) || audit._enc(coalesce(p_after::text,'{}')::bytea) || audit._enc(p_reason::bytea) || audit._enc(coalesce(p_metadata,'{}'::jsonb)::text::bytea), 'sha256');
 update audit.audit_log set row_hash=v_hash where id=v_id;
 update audit.audit_chain_head set last_id=v_id, last_row_hash=v_hash, updated_at=now() where id=true;
 return v_id;
end $$;
revoke execute on function audit.append_audit(uuid,text,text,text,text,jsonb,jsonb,text,jsonb) from public, anon, authenticated;
grant execute on function audit.append_audit(uuid,text,text,text,text,jsonb,jsonb,text,jsonb) to service_role;
create or replace function admin.current_admin_id() returns uuid language sql stable security definer set search_path='' as $$ select auth.uid() where exists (select 1 from admin.admin_profiles p where p.auth_user_id=auth.uid()) $$;
create or replace function admin.is_active_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists (select 1 from admin.admin_profiles p where p.auth_user_id=auth.uid() and p.status='active') $$;
create or replace function admin.has_aal2() returns boolean language sql stable security definer set search_path='' as $$ select coalesce(auth.jwt()->>'aal','aal1')='aal2' $$;
create or replace function admin.session_is_current() returns boolean language sql stable security definer set search_path='' as $$ select exists (select 1 from admin.admin_session_registry s where s.session_id=(auth.jwt()->>'session_id')::uuid and s.auth_user_id=auth.uid() and s.revoked_at is null) $$;
create or replace function admin.has_verified_totp_factor() returns boolean language sql stable security definer set search_path='' as $$ select exists (select 1 from auth.mfa_factors f where f.user_id=auth.uid() and f.factor_type='totp' and f.status='verified') $$;
create or replace function admin.has_permission(p_key text) returns boolean language sql stable security definer set search_path='' as $$ select admin.is_active_admin() and admin.has_aal2() and admin.session_is_current() and admin.has_verified_totp_factor() and exists (select 1 from admin.admin_role_assignments a join admin.role_permissions rp on rp.role_key=a.role_key where a.auth_user_id=auth.uid() and a.is_current and (a.expires_at is null or a.expires_at>now()) and rp.permission_key=p_key) $$;
create or replace function admin.has_step_up(p_action text, p_resource text) returns boolean language sql stable security definer set search_path='' as $$ select exists (select 1 from admin.admin_step_up_events e where e.auth_user_id=auth.uid() and e.session_id=(auth.jwt()->>'session_id')::uuid and e.action_key=p_action and (e.resource_key is not distinct from p_resource) and e.consumed_at is null and e.expires_at>now()) $$;
